import os
import time

from moler.exceptions import MolerException
from moler.helpers import call_base_class_method_with_same_name, mark_to_call_base_class_method_with_same_name

from ta_moler.device.nokia_unix_remote3 import NokiaUnixRemote3


@call_base_class_method_with_same_name
class UnixSyslog3(NokiaUnixRemote3):
    r"""
    Syslog device class.

    Example of device in yaml configuration file:
    - with PROXY_PC:
      UNIX_SYSLOG_PROXY_PC:
        DEVICE_CLASS: ta_moler.device.unix_syslog.UnixSyslog
        CONNECTION_HOPS:
          UNIX_LOCAL:
            PROXY_PC:
              execute_command: ssh
              command_params:
                expected_prompt: "proxy_pc#"
                host: proxy_pc_host
                login: proxy_pc_login
                password: password
          PROXY_PC:
            UNIX_REMOTE:
              execute_command: ssh
              command_params:
                host: unix_remote_host
                login: unix_remote_login
                password: password
                expected_prompt: "remote#"
          UNIX_REMOTE:
            PROXY_PC:
              command_params:
                expected_prompt: "proxy_pc#"
            SYSLOG:
              execute_command: start_syslog
              command_params:
                syslog_command: tail -F /tmp/syslog.log
    -without PROXY_PC:
      UNIX_SYSLOG:
        DEVICE_CLASS: ta_moler.device.unix_syslog.UnixSyslog
        CONNECTION_HOPS:
          UNIX_LOCAL:
            UNIX_REMOTE:
              execute_command: ssh
              command_params:
                host: unix_remote_host
                login: unix_remote_login
                password: password
                expected_prompt: "remote#"
          UNIX_REMOTE:
            SYSLOG:
              execute_command: start_syslog
              command_params:
                syslog_command: tail -F /tmp/syslog.log
    """

    syslog = "SYSLOG"

    def __init__(
        self,
        sm_params,
        name=None,
        io_connection=None,
        io_type=None,
        variant=None,
        io_constructor_kwargs=None,
        initial_state=None,
        lazy_cmds_events=False,
    ):
        """
        Create UnixSyslog device communicating over io_connection.

        :param sm_params: dict with parameters of state machine for device
        :param name: name of device
        :param io_connection: External-IO connection having embedded moler-connection
        :param io_type: type of connection - tcp, udp, ssh, telnet, ...
        :param variant: connection implementation variant, ex. 'threaded', 'twisted', 'asyncio', ...
                        (if not given then default one is taken)
        :param io_constructor_kwargs: additional parameter into constructor of selected connection type
                        (if not given then default one is taken)
        :param initial_state: name of initial state. State machine tries to enter this state just after creation.
        :param lazy_cmds_events: set False to load all commands and events when device is initialized, set True to load
                        commands and events when they are required for the first time.
        """
        initial_state = initial_state if initial_state is not None else UnixSyslog3.syslog
        super(UnixSyslog3, self).__init__(
            name=name,
            io_connection=io_connection,
            io_type=io_type,
            variant=variant,
            io_constructor_kwargs=io_constructor_kwargs,
            sm_params=sm_params,
            initial_state=initial_state,
            lazy_cmds_events=lazy_cmds_events,
        )
        self._sent_tail_last_log = False
        self.UnixSyslog_cmd = None

    def _get_unix_syslog_default_sm_configuration(self):
        config = {
            UnixSyslog3.connection_hops: {
                UnixSyslog3.unix_remote: {  # from
                    UnixSyslog3.syslog: {  # to
                        "execute_command": "start_syslog",  # using command
                        "command_params": {  # with parameters
                        },
                        "required_command_params": [],
                    }
                },
            }
        }
        return config

    @mark_to_call_base_class_method_with_same_name
    def _get_default_sm_configuration_with_proxy_pc(self):
        """
        Return State Machine default configuration with proxy_pc state.

        :return: default sm configuration with proxy_pc state.
        """
        return self._get_unix_syslog_default_sm_configuration()

    @mark_to_call_base_class_method_with_same_name
    def _get_default_sm_configuration_without_proxy_pc(self):
        """
        Return State Machine default configuration without proxy_pc state.

        :return: default sm configuration without proxy_pc state.
        """
        return self._get_unix_syslog_default_sm_configuration()

    def _prepare_transitions(self):
        super(UnixSyslog3, self)._prepare_transitions()
        transitions = {
            UnixSyslog3.syslog: {
                UnixSyslog3.unix_remote: {
                    "action": ["_stop_syslog_cmd"],
                }
            },
            UnixSyslog3.unix_remote: {
                UnixSyslog3.syslog: {
                    "action": ["_start_syslog_cmd"],
                }
            },
        }
        self._add_transitions(transitions=transitions)

    @mark_to_call_base_class_method_with_same_name
    def _prepare_state_hops_with_proxy_pc(self):
        state_hops = {
            UnixSyslog3.not_connected: {
                UnixSyslog3.syslog: UnixSyslog3.unix_local,
            },
            UnixSyslog3.proxy_pc: {
                UnixSyslog3.syslog: UnixSyslog3.unix_remote,
            },
            UnixSyslog3.unix_local: {
                UnixSyslog3.syslog: UnixSyslog3.proxy_pc,
            },
            UnixSyslog3.unix_local_root: {
                UnixSyslog3.syslog: UnixSyslog3.unix_local,
            },
            UnixSyslog3.syslog: {
                UnixSyslog3.proxy_pc: UnixSyslog3.unix_remote,
                UnixSyslog3.unix_local: UnixSyslog3.unix_remote,
                UnixSyslog3.unix_local_root: UnixSyslog3.unix_remote,
                UnixSyslog3.not_connected: UnixSyslog3.unix_remote,
                UnixSyslog3.unix_remote_root: UnixSyslog3.unix_remote,
            },
            UnixSyslog3.unix_remote_root: {UnixSyslog3.syslog: UnixSyslog3.unix_remote},
        }
        return state_hops

    @mark_to_call_base_class_method_with_same_name
    def _prepare_state_hops_without_proxy_pc(self):
        state_hops = {
            UnixSyslog3.not_connected: {
                UnixSyslog3.syslog: UnixSyslog3.unix_local,
            },
            UnixSyslog3.unix_local: {
                UnixSyslog3.syslog: UnixSyslog3.unix_remote,
            },
            UnixSyslog3.unix_local_root: {
                UnixSyslog3.syslog: UnixSyslog3.unix_local,
            },
            UnixSyslog3.syslog: {
                UnixSyslog3.unix_local: UnixSyslog3.unix_remote,
                UnixSyslog3.unix_local_root: UnixSyslog3.unix_remote,
                UnixSyslog3.not_connected: UnixSyslog3.unix_remote,
                UnixSyslog3.unix_remote_root: UnixSyslog3.unix_remote,
            },
            UnixSyslog3.unix_remote_root: {
                UnixSyslog3.syslog: UnixSyslog3.unix_remote,
            },
        }
        return state_hops

    def _get_packages_for_state(self, state, observer):
        available = super(UnixSyslog3, self)._get_packages_for_state(state, observer)

        if available and state == UnixSyslog3.unix_remote:
            available.append("ta_moler.cmd.unix_syslog")
            return available

        elif not available:
            if state == UnixSyslog3.syslog:
                available = {
                    UnixSyslog3.cmds: ["ta_moler.cmd.unix_syslog"],
                    UnixSyslog3.events: ["moler.events.shared", "moler.events.unix", "ta_moler.events.unix_syslog"],
                }

                return available[observer]

        return available

    # pylint: disable-next=unused-argument
    def _start_syslog_cmd(self, source_state, dest_state, timeout=-1):
        configurations = self.get_configurations(source_state=source_state, dest_state=dest_state)

        command_name = configurations["execute_command"]
        command_params = configurations["command_params"]
        command_timeout = 3600 * 24 * 365
        self.UnixSyslog_cmd = self.get_cmd(cmd_name=command_name, cmd_params=command_params)
        if "tail_last_log" in command_name:
            dir_to_script_x = self.UnixSyslog_cmd.command_path
            script_name = "ta_moler_tail_last_log.py"
            self._send_tail_last_log_command_content(dir_to_script_x=dir_to_script_x, script_name=script_name)
            time.sleep(0.5)

        self.UnixSyslog_cmd.start(timeout=command_timeout)
        time.sleep(0.5)
        if self.UnixSyslog_cmd.running():
            self._set_state(state=UnixSyslog3.syslog)

    # pylint: disable-next=unused-argument
    def _stop_syslog_cmd(self, source_state, dest_state, timeout=-1):
        self.UnixSyslog_cmd.break_cmd(force=True)
        try:
            self.UnixSyslog_cmd.await_done(timeout=2)
        except MolerException:
            pass
        self.UnixSyslog_cmd.cancel()
        self._set_state(state=UnixSyslog3.unix_remote)

    def _send_tail_last_log_command_content(self, dir_to_script_x, script_name):
        script_path = f"{dir_to_script_x}/{script_name}"
        if self._sent_tail_last_log is False:
            current_dir = os.path.dirname(os.path.abspath(__file__))
            dir_to_file = os.path.abspath(f"{current_dir}/../util/ta_moler_tail_last_log.py")
            with open(dir_to_file) as f:
                content = f.read()
            cmd_tee = self.get_cmd(cmd_name="tee", cmd_params={"path": script_path, "content": content})
            cmd_tee()
            cmd_chmod = self.get_cmd(cmd_name="chmod", cmd_params={"permission": "+x", "filename": script_path})
            cmd_chmod()
            try:
                cmd_df = self.get_cmd(cmd_name="df")
                cmd_df()
            except MolerException:
                pass

            self._sent_tail_last_log = True

    def goto_state(
        self, state, timeout=-1, rerun=0, send_enter_after_changed_state=False, log_stacktrace_on_fail=True, keep_state=True, timeout_multiply=1.0,
        sleep_after_changed_state=0.5
    ):
        """
        Go to specific state.

        :param state: Name to state to change on the device.
        :param timeout: Timeout for changing state, if negative then timeout from commands are taken.
        :param rerun: How many times rerun the procedure before it fails.
        :param send_enter_after_changed_state: If True then enter is sent after state is changed. False nothing is sent.
        :param log_stacktrace_on_fail: Set True to have stacktrace in logs when failed, otherwise False.
        :param keep_state: if True and state is changed without goto_state then device tries to change state to state
        defined by goto_state.
        :param timeout_multiply: how many times multiply passed timeout to get final timeout.
        :return: None
        :raise: DeviceChangeStateFailure if cannot change the state of device.
        """
        return super(UnixSyslog3, self).goto_state(
            state=state,
            timeout=timeout,
            rerun=rerun,
            send_enter_after_changed_state=send_enter_after_changed_state,
            log_stacktrace_on_fail=log_stacktrace_on_fail,
            keep_state=keep_state,
            timeout_multiply=timeout_multiply,
            sleep_after_changed_state=sleep_after_changed_state
        )
